<script setup>
import { ref,onMounted } from 'vue'
import { api,apiError } from '../services/api.js'
import { useAuthStore } from '../stores/authStore.js'
import ChatBox from '../components/ChatBox.vue'
const auth=useAuthStore(),items=ref([]),page=ref(0),totalPages=ref(0),selected=ref(null),messages=ref([]),messagePage=ref(0),messagePages=ref(0),error=ref(''),busy=ref(false)
async function load(next=0){busy.value=true;error.value='';try{const {data}=await api.get('/api/conversations',{params:{page:next}});items.value=data.items;page.value=next;totalPages.value=data.totalPages}catch(e){error.value=apiError(e)}finally{busy.value=false}}
async function select(c,older=false){error.value='';try{const next=older?messagePage.value+1:0;const {data}=await api.get(`/api/conversations/${c.id}/messages`,{params:{page:next}});selected.value=c;const batch=[...data.items].reverse();messages.value=older?[...batch,...messages.value]:batch;messagePage.value=next;messagePages.value=data.totalPages}catch(e){error.value=apiError(e)}}
async function hide(c){error.value='';try{await api.delete(`/api/conversations/${c.id}`);if(selected.value?.id===c.id){selected.value=null;messages.value=[]}await load(page.value)}catch(e){error.value=apiError(e)}}
onMounted(()=>load())
</script><template><main><header><RouterLink class="brand" to="/">← RandomConnect</RouterLink><nav class="account-nav"><RouterLink to="/friends">Bạn bè & chat riêng</RouterLink><RouterLink to="/profile">Hồ sơ</RouterLink></nav></header><h1>Lịch sử trò chuyện</h1><p>Chỉ hội thoại giữa hai tài khoản. Ẩn lịch sử của bạn không xóa bản mà đối tác còn được phép xem.</p><p v-if="error" class="error" role="alert">{{ error }}</p><div class="history-layout"><section class="panel history-list"><p v-if="!items.length">Chưa có cuộc trò chuyện được lưu.</p><article v-for="c in items" :key="c.id"><button @click="select(c)">{{ c.participants.filter(p=>p.id!==auth.user?.id).map(p=>p.displayName).join(', ') }} · {{ new Date(c.startedAt).toLocaleString() }}</button><small>{{ c.conversationType==='DIRECT'?'Chat riêng':c.status==='ACTIVE'?'Đang diễn ra':'Đã kết thúc' }}</small><RouterLink v-if="c.conversationType==='DIRECT'" :to="{path:'/friends',query:{user:c.participants.find(p=>p.id!==auth.user?.id)?.id}}">Tiếp tục chat riêng</RouterLink><button v-else class="danger" :disabled="c.status==='ACTIVE'" @click="hide(c)">Ẩn khỏi lịch sử của tôi</button></article><div class="controls"><button :disabled="page===0 || busy" @click="load(page-1)">Trước</button><span>{{ page+1 }} / {{ totalPages || 1 }}</span><button :disabled="page+1>=totalPages || busy" @click="load(page+1)">Sau</button></div></section><section v-if="selected"><button v-if="messagePage+1<messagePages" @click="select(selected,true)">Tải tin nhắn cũ hơn</button><ChatBox :messages="messages" :guest-id="auth.user?.id" read-only/></section></div></main></template>
